-- T0B-13.C14 schema suite: smartreport catalogue properties (C14 05-SCHEMA §1, §4, §5, §6, §9; AC-0B-2.1, 2.2, 2.3, 2.4, 3.6, 4.1, 4.2, 4.3, 5.1, 5.3, 6.1, 6.2, 6.3).
-- Pure pg_catalog assertions: no fixtures, no data written. One rolled-back transaction. RLS is never disabled.
-- Run from the repo root: pg_prove -d <db> db/tests/smartreport/T0B-13.C14_schema.test.sql   (pgTAP in schema `extensions`; migrations + seeds loaded; superuser)
-- Markers (the node test checks them): C14 check 1 inventory/owner/no sequences, enums or views, 2 RLS ENABLE+FORCE (G exempt), 3 policy set per table (29, no DELETE policy, staff + actor guard), 4 grant matrix (no DELETE anywhere),
-- 5 indexes + constraint names, 6 triggers + functions (INVOKER) + audit, 7 FK direction + no DEFINER + seeds + registry (AC-0B-6.1 / 6.2 / 6.3). Check 8 and "C14 test 1-13" (05-SCHEMA §10) are in T0B-13.C14_behaviour.test.sql.
-- Scope note: event_inbox is C0's (T0B-05) and is excluded from every count. lims_api / lims_worker INHERIT lims_app, so "no DELETE / no UPDATE" is asserted for lims_app only.
-- Tester assumption (see note T0B-13.C14-tests.md): audit trigger on every class M / C table (7), none on class A (4) or G (3) - 05-SCHEMA §9 comment "C0 attaches its generic audit trigger (04 D11) to every table above except the class-A tables and event_inbox".
BEGIN;
SET search_path = extensions, public, pg_catalog;
SELECT * FROM no_plan();

-- t: table; cls: §1 class; centre: §1 scope; u: lims_app UPDATE grant; npol: expected policies; aud: audit trigger expected
CREATE TEMP TABLE rt(t, cls, centre, u, npol, aud) AS VALUES
  ('library_versions','M',false,true,3,true),('template_blocks','M',false,true,3,true),('rules','M',false,true,3,true),('analyte_groups','M',false,true,3,true),('group_settings','M',false,true,3,true),
  ('wording_deny_terms','M',false,true,3,true),('library_reviews','A',false,false,2,false),('summaries','C',true,true,3,true),('summary_report_bindings','A',true,false,2,false),
  ('summary_reviews','A',true,false,2,false),('llm_runs','A',true,false,2,false);
CREATE TEMP TABLE rg(t) AS VALUES ('g_cs_organ_groups'),('g_cs_summary_reject_reasons'),('g_cs_wording_deny_terms');
CREATE TEMP TABLE rf(f) AS VALUES ('assert_library_draft'),('check_library_transition'),('check_summary_transition');

-- C14 check 1: inventory, owner (AC-0B-1.2, AC-0B-6.3), schema privileges, no sequences / enums / views (§8)
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'smartreport'::regnamespace AND c.relkind IN ('r','p')), 11 + 3 + 1, 'C14 check 1: smartreport holds 11 tenant + 3 G tables + event_inbox (14 chunk tables + inbox)');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'smartreport'::regnamespace AND c.relkind IN ('v','m')), 0, 'C14 check 1 / §8: no view and no materialized view (C14 publishes none)');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'smartreport'::regnamespace AND c.relkind = 'S'), 0, 'C14 check 1: no sequences');
SELECT is((SELECT count(*)::int FROM pg_type t WHERE t.typnamespace = 'smartreport'::regnamespace AND t.typtype = 'e'), 0, 'C14 check 1: no ENUM types');
SELECT is(pg_get_userbyid(c.relowner), 'lims_owner', 'C14 check 1: smartreport.' || c.relname || ' owned by lims_owner (AC-0B-1.2, AC-0B-6.3)') FROM pg_class c WHERE c.relnamespace = 'smartreport'::regnamespace AND c.relkind = 'r';
SELECT is(has_schema_privilege('lims_app', 'smartreport', 'USAGE'), true, 'lims_app has USAGE on schema smartreport');
SELECT is(has_schema_privilege(r, 'smartreport', 'CREATE'), false, r || ' cannot CREATE in smartreport') FROM unnest(ARRAY['lims_app','lims_api','lims_worker','lims_analytics']) r;
SELECT is((SELECT count(*)::int FROM rt) + (SELECT count(*)::int FROM rg), 14, 'C14 check 1: 14 tables in the inventory (= table count of the 05-SCHEMA §9 DDL)');
SELECT is((SELECT array_agg(relname::text ORDER BY relname) FROM pg_class WHERE relnamespace = 'smartreport'::regnamespace AND relkind = 'r' AND relname <> 'event_inbox'), (SELECT array_agg(t ORDER BY t) FROM (SELECT t FROM rt UNION ALL SELECT t FROM rg) x), 'C14 check 1: the table set equals the §1 inventory');

-- C14 check 2: RLS ENABLE + FORCE on the 11 tenant tables, none on the 3 G tables (AC-0B-2.1, 2.4)
SELECT is((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid = ('smartreport.' || t)::regclass), true, 'C14 check 2 / AC-0B-2.1: ENABLE + FORCE RLS on smartreport.' || t) FROM rt;
SELECT is((SELECT relrowsecurity OR relforcerowsecurity FROM pg_class WHERE oid = ('smartreport.' || t)::regclass), false, 'C14 check 2 / AC-0B-2.1: smartreport.' || t || ' is RLS-exempt (global coded set, listed in rls_exempt.txt)') FROM rg;
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'smartreport' AND tablename = g.t), 0, 'C14 check 2: no policy on ' || g.t) FROM rg g;
SELECT is(NOT EXISTS (SELECT 1 FROM pg_class WHERE relnamespace = 'smartreport'::regnamespace AND relkind = 'r' AND relname <> 'event_inbox' AND relname NOT LIKE 'g\_%' AND NOT (relrowsecurity AND relforcerowsecurity)), true, 'C14 check 2 / AC-0B-2.2 / AC-0B-2.4: no smartreport tenant table without FORCE RLS (RLS is never off)');
SELECT is((SELECT count(*)::int FROM information_schema.columns WHERE table_schema = 'smartreport' AND column_name = 'tenant_id' AND is_nullable = 'YES'), 0, 'C14 check 2 / AC-0B-3.5: tenant_id is NOT NULL everywhere');

-- C14 check 3: policy set per table (AC-0B-2.3): 29 policies, TO lims_app, SELECT + INSERT (+ UPDATE except class A), staff + actor guard, ::uuid[] cast, no DELETE policy (§4, §6)
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'smartreport' AND tablename = rt.t), npol, 'C14 check 3 / AC-0B-2.3: smartreport.' || t || ' has ' || npol || ' policies') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'smartreport' AND tablename <> 'event_inbox'), 29, 'C14 check 3: 29 policies in smartreport (ex event_inbox)');
SELECT is((SELECT array_agg(DISTINCT r ORDER BY r) FROM pg_policies p, unnest(p.roles) r WHERE schemaname = 'smartreport' AND tablename <> 'event_inbox'), ARRAY['lims_app'::name], 'C14 check 3: every policy is TO lims_app only (no PUBLIC / anon / owner_only)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'smartreport' AND tablename = rt.t AND cmd = 'UPDATE'), CASE WHEN u THEN 1 ELSE 0 END, 'C14 check 3: UPDATE policy on smartreport.' || t || ' iff a lims_app UPDATE grant exists (class A tables: none)') FROM rt;
-- T0B-GREEN-1 STALE: migration 20261105001000 (core__create_event_inboxes) adds event_inbox__delete__owner_only to every schema's event_inbox (purge by lims_owner); the check keeps its meaning for every other table and pins the inbox policy to lims_owner
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'smartreport' AND tablename <> 'event_inbox' AND cmd = 'DELETE'), 0, 'C14 check 3 / §9: no DELETE policy on any smartreport table (REQ-SEC-016 default deny; class M rows are deactivated)');
SELECT is((SELECT array_agg(policyname::text || '|' || roles::text) FROM pg_policies WHERE schemaname = 'smartreport' AND tablename = 'event_inbox' AND cmd = 'DELETE'), ARRAY['event_inbox__delete__owner_only|{lims_owner}'], 'C14 check 3 / T0B-GREEN-1: the only DELETE policy of the schema is the event_inbox owner-only purge policy, TO lims_owner only');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'smartreport' AND tablename <> 'event_inbox' AND NOT (coalesce(qual, '') || coalesce(with_check, '')) LIKE '%is_staff_or_system%'), 0, 'C14 check 3 / P-16: staff-actor guard in every smartreport policy (gate 9)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'smartreport' AND tablename <> 'event_inbox' AND NOT (coalesce(qual, '') || coalesce(with_check, '')) LIKE '%current_actor_type%'), 0, 'C14 check 3 / D-109: actor-type list in every smartreport policy (device, patient, portal, partner excluded)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'smartreport' AND tablename <> 'event_inbox' AND (coalesce(qual, '') || coalesce(with_check, '')) ~ '(device|patient|portal|partner)'), 0, 'C14 check 3 / 08 A2.3: no policy names a non-staff actor (no patient / portal / partner / device access, none will be added)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'smartreport' AND policyname LIKE '%\_\_tenant\_centre' AND (coalesce(qual, '') || coalesce(with_check, '')) NOT LIKE '%::uuid[]%'), 0, 'C14 check 3 / A16.1: centre policies carry the ::uuid[] cast');
SELECT is((SELECT array_agg(DISTINCT tablename::text ORDER BY tablename::text) FROM pg_policies WHERE schemaname = 'smartreport' AND policyname LIKE '%\_\_tenant\_centre'), (SELECT array_agg(t ORDER BY t) FROM rt WHERE centre), 'C14 check 3: centre scope exactly on summaries, summary_report_bindings, summary_reviews, llm_runs');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'smartreport' AND tablename IN (SELECT t FROM rt WHERE NOT centre) AND (coalesce(qual, '') || coalesce(with_check, '')) ~ '(current_centre_ids|has_all_centres)'), 0, 'C14 check 3: library tables and deny terms are tenant-only (no centre predicate)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'smartreport' AND tablename <> 'event_inbox' AND (coalesce(qual, '') || coalesce(with_check, '')) NOT LIKE '%current_tenant_id%'), 0, 'C14 check 3: tenant predicate in every policy');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'smartreport' AND tablename <> 'event_inbox' AND policyname !~ ('^' || tablename || '__(select|insert|update)__(tenant|tenant_centre)$')), 0, 'C14 check 3: policy names are <table>__<cmd>__(tenant|tenant_centre)');

-- C14 check 4: grant matrix (AC-0B-4.2 / 4.3; §6): INSERT everywhere, UPDATE only on the 7 mutable tables, DELETE nowhere (§10 test 3)
SELECT is(has_table_privilege('lims_app', 'smartreport.' || t, 'SELECT'), true, 'C14 check 4: lims_app SELECT on smartreport.' || t) FROM rt;
SELECT is(has_table_privilege('lims_app', 'smartreport.' || t, 'INSERT'), true, 'C14 check 4 / AC-0B-4.2: lims_app INSERT on smartreport.' || t) FROM rt;
SELECT is(has_table_privilege('lims_app', 'smartreport.' || t, 'UPDATE'), u, 'C14 check 4 / AC-0B-4.1 / AC-0B-4.3: lims_app UPDATE on smartreport.' || t || ' (none on the 4 class-A tables)') FROM rt;
SELECT is(has_table_privilege('lims_app', 'smartreport.' || t, 'DELETE'), false, 'C14 check 4 / AC-0B-4.2 / §10 test 3: lims_app has no DELETE on smartreport.' || t) FROM (SELECT t FROM rt UNION ALL SELECT t FROM rg) x(t);
SELECT is(has_table_privilege('lims_app', 'smartreport.' || t, 'TRUNCATE') OR has_table_privilege('lims_app', 'smartreport.' || t, 'REFERENCES') OR has_table_privilege('lims_app', 'smartreport.' || t, 'TRIGGER'), false, 'C14 check 4: no TRUNCATE / REFERENCES / TRIGGER on smartreport.' || t) FROM rt;
SELECT is(ARRAY[has_table_privilege('lims_app', 'smartreport.' || t, 'SELECT'), has_table_privilege('lims_app', 'smartreport.' || t, 'INSERT'), has_table_privilege('lims_app', 'smartreport.' || t, 'UPDATE'), has_table_privilege('lims_app', 'smartreport.' || t, 'DELETE')], ARRAY[true, false, false, false], 'C14 check 4: lims_app only SELECTs ' || t) FROM rg;
SELECT is(has_table_privilege('lims_analytics', 'smartreport.' || x.t, p), false, 'C14 check 4: lims_analytics has no ' || p || ' on smartreport.' || x.t) FROM (SELECT t FROM rt UNION ALL SELECT t FROM rg) x, unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE']) p;
SELECT is((SELECT count(*)::int FROM information_schema.role_table_grants WHERE table_schema = 'smartreport' AND grantee IN ('PUBLIC','anon','authenticated','service_role')), 0, 'C14 check 4: nothing granted to PUBLIC / anon / authenticated / service_role');

-- C14 check 5: indexes (§5) and constraint names: tenant_id leads every index; the 14 named indexes exist; every __p_ index is partial; UNIQUE (tenant_id, id) on all 11 tenant tables; tenant FK; composite rule -> block FK
SELECT is((regexp_match(pg_get_indexdef(i.indexrelid), '\(([^,)]+)'))[1], 'tenant_id', 'C14 check 5: index ' || c.relname || ' leads with tenant_id') FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class t ON t.oid = i.indrelid
  WHERE t.relnamespace = 'smartreport'::regnamespace AND t.relname NOT LIKE 'g\_%' AND t.relname <> 'event_inbox' AND NOT i.indisprimary;
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'smartreport' AND indexname = n), 1, 'C14 check 5: index ' || n || ' exists (§5 / §9)')
  FROM unnest(ARRAY['library_versions__tenant_id__open__p_uq','library_versions__tenant_id__approved__p_uq','template_blocks__tenant_id_lib_key__p_uq','rules__tenant_id_library_version_id_rule_kind__idx','rules__tenant_id_block__idx',
  'analyte_groups__tenant_id_lib_analyte__p_uq','wording_deny_terms__tenant_id_term_folded_language__p_uq','library_reviews__tenant_id_library_version_id_created_at__idx','summaries__tenant_id_order_id__live__p_uq',
  'summaries__tenant_id_status_built_at__idx','summaries__tenant_id_centre_id_status_built_at__idx','summaries__tenant_id_order_id_built_at__idx','summary_reviews__tenant_id_summary_id_created_at__idx','llm_runs__tenant_id_summary_id_created_at__idx']) n;
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'smartreport' AND tablename <> 'event_inbox' AND indexname NOT IN (SELECT conname FROM pg_constraint WHERE connamespace = 'smartreport'::regnamespace)), 14, 'C14 check 5: exactly the 14 spec indexes beyond the constraint-backed ones (no extra / trigram index)');
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'smartreport' AND indexname ~ '__p_(uq|idx)$' AND indexdef NOT LIKE '% WHERE %'), 0, 'C14 check 5: every __p_ index is partial');
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'smartreport' AND indexname IN ('template_blocks__tenant_id_lib_key__p_uq', 'analyte_groups__tenant_id_lib_analyte__p_uq') AND indexdef LIKE '%WHERE is_active%'), 2, 'C14 check 5 / P-18(a): key / analyte unique among ACTIVE rows (deactivation frees the key)');
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = ('smartreport.' || t)::regclass AND contype = 'u' AND conkey @> ARRAY[(SELECT attnum FROM pg_attribute WHERE attrelid = ('smartreport.' || t)::regclass AND attname = 'tenant_id'), (SELECT attnum FROM pg_attribute WHERE attrelid = ('smartreport.' || t)::regclass AND attname = 'id')] AND cardinality(conkey) = 2), 1, 'C14 check 5: UNIQUE (tenant_id, id) on smartreport.' || t || ' (04 D8)') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_constraint c JOIN pg_class r ON r.oid = c.conrelid WHERE r.relnamespace = 'smartreport'::regnamespace AND r.relkind = 'r' AND r.relname <> 'event_inbox' AND c.conname NOT LIKE r.relname || '\_\_%'), 0, 'C14 check 5: every constraint in smartreport is prefixed <table>__');
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = ('smartreport.' || t)::regclass AND conname = t || '__tenant__fk' AND contype = 'f' AND confrelid = 'core.tenants'::regclass), 1, 'C14 check 5 / C0 §9 rule 1: ' || t || '__tenant__fk -> core.tenants') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = 'smartreport.rules'::regclass AND conname = 'rules__block__fk' AND contype = 'f' AND confrelid = 'smartreport.template_blocks'::regclass AND cardinality(conkey) = 4), 1, 'C14 check 5 / §10 test 8: rules -> template_blocks is the 4-column FK (tenant_id, library_version_id, block_id, block_kind)');
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = 'smartreport.rules'::regclass AND conname IN ('rules__analyte__fk', 'rules__test__fk') AND contype = 'f' AND cardinality(conkey) = 2), 2, 'C14 check 5 / §10 test 8: rules -> catalog.analytes / catalog.tests are composite (tenant_id, id) FKs');
SELECT is((SELECT count(*)::int FROM pg_constraint c WHERE c.contype = 'f' AND c.conrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'smartreport'::regnamespace AND relname NOT LIKE 'g\_%' AND relname <> 'event_inbox')
  AND cardinality(c.conkey) = 1 AND c.confrelid <> 'core.tenants'::regclass AND c.confrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace = 'smartreport'::regnamespace AND relname LIKE 'g\_%')), 0, 'C14 check 5: every FK except the tenant FK and the 4 FKs to a G table is composite (tenant_id, x) (02-CV §5.4)');
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE connamespace = 'smartreport'::regnamespace AND conname IN ('rules__followup_fields__ck', 'summaries__inputs__ck', 'library_versions__hash__ck', 'summaries__llm__ck', 'library_versions__credits__ck', 'rules__trigger_fields__ck') AND contype = 'c'), 6, 'C14 check 5: the named CHECKs of §10 tests 9 and 13 (and the library / summary invariants) exist');
SELECT is((SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conname = 'summaries__inputs__ck' AND conrelid = 'smartreport.summaries'::regclass) ~ '2000', true, 'C14 check 5 / §10 test 13: the input_result_versions cap is 2000 [CONV]');

-- C14 check 6: triggers, functions, audit (AC-0B-4.1, 5.1, 5.3): 9 spec triggers, 3 INVOKER functions, 7 audit triggers
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid = ('smartreport.' || t)::regclass AND NOT tg.tgisinternal AND tg.tgname = t || '__audit'), CASE WHEN aud THEN 1 ELSE 0 END, 'C14 check 6 / AC-0B-5.1: audit trigger on smartreport.' || t || ' iff class M / C') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid = ('smartreport.' || t)::regclass AND tg.tgname = t || '__audit' AND tg.tgfoid = 'app.tg_row_audit'::regproc), CASE WHEN aud THEN 1 ELSE 0 END, 'C14 check 6: audit trigger of smartreport.' || t || ' runs app.tg_row_audit') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'smartreport'::regnamespace) AND NOT tg.tgisinternal AND tg.tgname LIKE '%\_\_audit'), 7, 'C14 check 6 / AC-0B-5.3: 7 audit triggers (6 M, 1 C); none on the class-A tables or the G tables');
SELECT is((SELECT array_agg(tgname::text ORDER BY tgname::text) FROM pg_trigger WHERE tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'smartreport'::regnamespace) AND NOT tgisinternal AND tgname NOT LIKE '%\_\_audit' AND tgname NOT LIKE '%event_inbox%'),
  ARRAY['analyte_groups__draft_only','group_settings__draft_only','library_versions__mutable_columns','library_versions__transition','rules__draft_only','summaries__llm_draft_only','summaries__mutable_columns','summaries__transition','template_blocks__draft_only'], 'C14 check 6: exactly the 9 spec triggers by name');
SELECT is((SELECT count(*)::int FROM pg_trigger WHERE tgrelid = ('smartreport.' || t)::regclass AND tgname = t || '__draft_only' AND tgfoid = 'smartreport.assert_library_draft'::regproc AND (tgtype & 1) = 1 AND (tgtype & 2) = 2 AND (tgtype & 4) = 4 AND (tgtype & 8) = 8 AND (tgtype & 16) = 16), 1,
  'C14 check 6 / §4: smartreport.' || t || ' draft_only is BEFORE INSERT OR UPDATE OR DELETE FOR EACH ROW (DELETE = defence in depth)') FROM unnest(ARRAY['template_blocks','rules','analyte_groups','group_settings']) t;
SELECT is((SELECT count(*)::int FROM pg_trigger WHERE tgrelid = 'smartreport.library_versions'::regclass AND tgname = 'library_versions__transition' AND tgfoid = 'smartreport.check_library_transition'::regproc AND (tgtype & 2) = 2 AND (tgtype & 16) = 16), 1, 'C14 check 6 / §4: library_versions__transition is BEFORE UPDATE');
SELECT is((SELECT count(*)::int FROM pg_trigger WHERE tgrelid = 'smartreport.summaries'::regclass AND tgname = 'summaries__transition' AND tgfoid = 'smartreport.check_summary_transition'::regproc AND (tgtype & 2) = 2 AND (tgtype & 16) = 16), 1, 'C14 check 6 / §4: summaries__transition is BEFORE UPDATE');
SELECT is((SELECT count(*)::int FROM pg_trigger WHERE tgrelid = ('smartreport.' || x.t)::regclass AND tgname = x.n AND tgfoid = 'app.enforce_mutable_columns'::regproc AND (tgtype & 2) = 2 AND (tgtype & 16) = 16), 1, 'C14 check 6 / §4: ' || x.n || ' is BEFORE UPDATE via app.enforce_mutable_columns')
  FROM (VALUES ('library_versions','library_versions__mutable_columns'),('summaries','summaries__mutable_columns'),('summaries','summaries__llm_draft_only')) x(t, n);
SELECT is((SELECT count(*)::int FROM pg_trigger WHERE tgrelid IN ('smartreport.library_versions'::regclass, 'smartreport.summaries'::regclass) AND tgname IN ('library_versions__mutable_columns', 'summaries__llm_draft_only') AND pg_get_triggerdef(oid) ~ 'WHEN .*status.*<> ''draft''::text'), 2, 'C14 check 6 / §4: the two frozen-outside-draft triggers carry WHEN (OLD.status <> draft)');
SELECT is((SELECT count(*)::int FROM pg_proc p WHERE p.pronamespace = 'smartreport'::regnamespace AND p.proname = f), 1, 'C14 check 6: smartreport.' || f || '() exists') FROM rf;
SELECT is((SELECT prosecdef FROM pg_proc WHERE pronamespace = 'smartreport'::regnamespace AND proname = f), false, 'C14 check 6 / AC-0B-4.1 / 04 D7: smartreport.' || f || ' is SECURITY INVOKER (no DEFINER, no inventory row)') FROM rf;
SELECT is((SELECT proconfig FROM pg_proc WHERE pronamespace = 'smartreport'::regnamespace AND proname = f), ARRAY['search_path=""'], 'C14 check 6: smartreport.' || f || ' has search_path = empty') FROM rf;
SELECT is((SELECT pg_get_userbyid(proowner) FROM pg_proc WHERE pronamespace = 'smartreport'::regnamespace AND proname = f), 'lims_owner', 'C14 check 6: smartreport.' || f || ' owned by lims_owner (AC-0B-6.3)') FROM rf;
SELECT is((SELECT count(*)::int FROM pg_proc WHERE pronamespace = 'smartreport'::regnamespace), 3, 'C14 check 6: no function in smartreport beyond the 3 trigger functions');

-- C14 check 7: FK direction, no DEFINER, no view, seeds (AC-0B-6.1 / 6.2 / 6.3; REQ-SEC-031)
SELECT is((SELECT array_agg(DISTINCT n.nspname::text ORDER BY n.nspname::text) FROM pg_constraint c JOIN pg_class r ON r.oid = c.confrelid JOIN pg_namespace n ON n.oid = r.relnamespace WHERE c.contype = 'f' AND c.conrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'smartreport'::regnamespace)),
  ARRAY['catalog','core','frontdesk','smartreport'], 'C14 check 7 / AC-0B-6.2: smartreport FKs point into smartreport, core, catalog, frontdesk only (01 §5 R3)');
SELECT is((SELECT count(*)::int FROM pg_constraint c JOIN pg_class r ON r.oid = c.confrelid WHERE c.contype = 'f' AND r.relnamespace = 'smartreport'::regnamespace AND c.conrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace = 'smartreport'::regnamespace)), 0, 'C14 check 7 / AC-0B-6.2: nothing references smartreport from another schema');
SELECT is((SELECT count(*)::int FROM pg_constraint c WHERE c.contype = 'f' AND c.conrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'smartreport'::regnamespace AND relkind = 'r') AND c.confrelid IN (SELECT oid FROM pg_class WHERE relnamespace IN ('billing'::regnamespace, 'lab'::regnamespace, 'reporting'::regnamespace, 'analytics'::regnamespace))), 0, 'C14 check 7: no FK into billing / lab / reporting / analytics (02-CV §5.4)');
SELECT is((SELECT count(*)::int FROM pg_proc WHERE pronamespace = 'smartreport'::regnamespace AND prosecdef), 0, 'C14 check 7: no SECURITY DEFINER function in smartreport');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'smartreport'::regnamespace AND c.relkind = 'r' AND c.relname IN (SELECT t FROM rt)), 11, 'C14 check 7 / AC-0B-6.1: all 11 tenant tables exist after the migrations applied in order');
SELECT is((SELECT count(*)::int FROM smartreport.g_cs_organ_groups WHERE system = 'lims' AND system_version = '1' AND is_active), 16, 'C14 check 7 / §3.1: 16 organ groups seeded (system lims, version 1, active)');
SELECT is((SELECT array_agg(code ORDER BY sort_order) FROM smartreport.g_cs_organ_groups), ARRAY['blood_counts','glucose','lipids','liver','kidney','electrolytes','thyroid','iron','vitamins','inflammation','hormones','immunology','urine','stool','vitals','other'], 'C14 check 7 / §3.1: organ group codes in sort order (10 .. 150, other 900)');
SELECT is((SELECT array_agg(code || ':' || display || ':' || sort_order ORDER BY sort_order) FROM smartreport.g_cs_summary_reject_reasons), ARRAY['wording_problem:Wording not appropriate:10','library_error:Library rule or text error:20','not_appropriate_for_patient:Not appropriate for this patient:30','results_under_review:Results under review:40','other:Other:90'], 'C14 check 7 / §3.2: 5 reject reasons');
SELECT is((SELECT count(*)::int FROM smartreport.g_cs_wording_deny_terms WHERE is_active AND reason = 'global wording rule (04 R8)'), 23, 'C14 check 7 / §3.3: 23 global deny terms with the spec reason');
SELECT is((SELECT array_agg(term_folded ORDER BY term_folded) FROM smartreport.g_cs_wording_deny_terms WHERE language = 'any'), ARRAY['http','www.'], 'C14 check 7 / §3.3: http and www. are language any, the other 21 are en');
SELECT is((SELECT count(*)::int FROM smartreport.g_cs_wording_deny_terms WHERE language = 'en' AND term = term_folded), 21, 'C14 check 7 / §3.3: 21 English terms, term = term_folded');
SELECT is((SELECT count(*)::int FROM smartreport.library_versions) + (SELECT count(*)::int FROM smartreport.summaries) + (SELECT count(*)::int FROM smartreport.template_blocks) + (SELECT count(*)::int FROM smartreport.rules) + (SELECT count(*)::int FROM smartreport.wording_deny_terms), 0, 'C14 check 7: no tenant library / summary data is seeded (the library is cloned or built by the service)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'storage' AND policyname LIKE 'smartreport%'), 0, 'C14 check 7: no storage policy is created by SQL');

SELECT * FROM finish();
ROLLBACK;
